import{_ as t,o as a,c as s,a0 as r}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Follow along: export documents with background jobs","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/document-exports"},"headers":[],"relativePath":"en/tutorials/document-exports.md","filePath":"en/tutorials/document-exports.md"}'),n={name:"en/tutorials/document-exports.md"};function o(i,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="follow-along-export-documents-with-background-jobs" tabindex="-1">Follow along: export documents with background jobs <a class="header-anchor" href="#follow-along-export-documents-with-background-jobs" aria-label="Permalink to &quot;Follow along: export documents with background jobs&quot;">​</a></h1><p>Sign in, open a saved document and click &quot;Export this document&quot; under &quot;Document exports&quot;. The page immediately shows &quot;Queued&quot;, and once the Worker finishes, &quot;Download ZIP&quot; appears. Records are listed newest first; a new request returns to the first page with its progress, and the record survives a page refresh. A Reader can also export documents they are allowed to read. The ZIP contains <code>document.md</code> and an attachments directory, suitable for taking a single document offline.</p><p>This path splits a time-consuming action away from the HTTP request: the API persists the user&#39;s request, and the Worker completes it. Jobs live in PostgreSQL, so stopping the Worker never strands pending records in memory; this chapter needs no RabbitMQ.</p><h2 id="_1-start-it-and-actually-use-it" tabindex="-1">1. Start it and actually use it <a class="header-anchor" href="#_1-start-it-and-actually-use-it" aria-label="Permalink to &quot;1. Start it and actually use it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>The development entry now starts PostgreSQL/RustFS, runs migrations and storage initialization, then starts the API, the Worker and the Web app. Rust source changes restart the API and the Worker; the web app uses HMR. The Worker&#39;s default health port is <code>127.0.0.1:3001</code>.</p><p>Create a Markdown document, upload a text attachment, then request an export. Download the ZIP and confirm both the body and the attachment are inside. To observe the waiting state you can start a Worker on its own with the command below; with only the API/Web running, requests still enqueue.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worker</span></span></code></pre></div><p><code>just worker</code> loads the same <code>.env.example</code> / <code>.env</code> plus the process environment and starts one real Worker. Do not let it fight <code>just dev</code>&#39;s Worker for the default health port; give the second process its own <code>WORKER_BIND</code>.</p><p>The Worker&#39;s <code>/health/live</code> says the process is alive; <code>/health/ready</code> also checks that the loop has started and the full migration history is present. <code>Ctrl+C</code> first stops claiming jobs, then gives the current job a bounded finish window; the database and object-storage volumes remain.</p><h2 id="_2-persist-a-snapshot-at-request-time" tabindex="-1">2. Persist a snapshot at request time <a class="header-anchor" href="#_2-persist-a-snapshot-at-request-time" aria-label="Permalink to &quot;2. Persist a snapshot at request time&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/crates/app/src/modules/knowledge/exports/mod.rs" target="_blank" rel="noreferrer">export API</a> verifies read access to the current document and saves, in one transaction:</p><ul><li>the export ID and requester;</li><li>the document version, title, Markdown and the ready attachment list;</li><li>stable references to the original credentials;</li><li>the PostgreSQL job and the audit entry.</li></ul><p>The job payload only carries <code>export_id</code>; it never copies bodies or storage URLs. The original session ID is used for re-verification later; passwords, the cookie secret and hashes never enter the job payload.</p><p>An Idempotency-Key identifies one export request. Retrying with the same key after a lost response returns the same export; editing the document meanwhile does not rewrite that snapshot. The next deliberate click after a successful request creates a new request, used to export a newer version. If the audit or another database write fails, the export, snapshot, job and idempotency record roll back together.</p><h2 id="_3-core-jobs-and-the-knowledge-base-handler" tabindex="-1">3. Core jobs and the knowledge-base handler <a class="header-anchor" href="#_3-core-jobs-and-the-knowledge-base-handler" aria-label="Permalink to &quot;3. Core jobs and the knowledge-base handler&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/crates/app/src/modules/jobs/mod.rs" target="_blank" rel="noreferrer">Core Jobs</a> claim work with short <code>FOR UPDATE SKIP LOCKED</code> transactions, updating attempt count, executor, lease token and deadline before committing. The following network I/O and ZIP generation never hold the claim transaction.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/crates/app/src/modules/jobs/worker.rs" target="_blank" rel="noreferrer">Worker</a> only claims registered job types and advances its own lease renewal while processing. While a renewal waits on a row lock the business keeps running; a failed renewal first cancels the handler and releases its transaction, then records the failure, so the worker never waits on a lock it holds itself. A completion commit must still match the token and hold an unexpired lease. The knowledge-base <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/crates/app/src/modules/knowledge/exports/worker.rs" target="_blank" rel="noreferrer">handler</a> owns its snapshot, permissions and business outcome; Core never queries knowledge tables.</p><p>The Worker re-checks the requester and the original credentials, the source document and its attachments when processing starts, when the candidate is created and at final publication. Signing out of the requesting session, deactivating the member, revoking a grant or losing an input after the request all prevent a downloadable success. A completed export stays accessible under current permissions even after the user signs in with a new session.</p><p>The base queue already separates transient from permanent errors, with budgeted backoff and reclaiming of expired leases. Continue with <a href="./job-recovery">job recovery and administrator retries</a> to verify crashes, stale executors, attempt history and admin retries.</p><h2 id="_4-bounded-memory-and-a-safe-zip" tabindex="-1">4. Bounded memory and a safe ZIP <a class="header-anchor" href="#_4-bounded-memory-and-a-safe-zip" aria-label="Permalink to &quot;4. Bounded memory and a safe ZIP&quot;">​</a></h2><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/crates/app/src/modules/knowledge/exports/archive.rs" target="_blank" rel="noreferrer">ZIP implementation</a> never keeps the whole ZIP or all attachments in memory:</p><ol><li>It streams one S3 object sequentially into a <code>0700</code> temporary directory, counting and verifying SHA-256 as it goes;</li><li>a blocking thread writes the ZIP in chunks from the temporary input file, bounding the actual output length including ZIP headers and the central directory;</li><li>after the ZIP writer is closed, the final file is re-read to compute its checksum;</li><li>the file is uploaded with a conditional PUT over a file byte stream.</li></ol><p>The ZIP&#39;s Stored mode does not compress, which keeps the design easy to follow and bounds CPU cost. Internal paths are <code>document.md</code> and <code>attachments/&lt;File ID&gt;.&lt;safe extension&gt;</code>; user file names never become directory paths and same-named attachments never collide.</p><p>Markdown is parsed first, and only <code>attachment:&lt;UUID&gt;</code> references that belong to the snapshot are rewritten inside Link/Image nodes to relative ZIP paths; the same string inside code or plain text stays text. When attachment references exist, re-serialization may normalize whitespace, escapes and reference-style links; the export guarantees the snapshot&#39;s semantics, not every formatting byte of the original Markdown. Unknown attachment references keep their original target — other files are never pulled in, and external URLs are never fetched.</p><p>At most one export per process holds the packaging resources. A total deadline covers download, ZIP and publication; blocking code checks cancellation per chunk. Once <code>spawn_blocking</code> has started it cannot be force-aborted, so the thread holds the temporary directory and the concurrency permit until it actually exits. Ordinary success/failure cleans up local files; SIGKILL or a filesystem failure may leave a temporary directory behind, and Drop must not be treated as a crash-cleanup guarantee. The temporary disk takes no part in backups; a failed job can be rebuilt from the database snapshot.</p><p>For the primary sources and exact crate versions see the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/docs/research/document-export-streaming.md" target="_blank" rel="noreferrer">streaming research</a> note.</p><h2 id="_5-object-writes-and-the-database-publication" tabindex="-1">5. Object writes and the database publication <a class="header-anchor" href="#_5-object-writes-and-the-database-publication" aria-label="Permalink to &quot;5. Object writes and the database publication&quot;">​</a></h2><p>Before the generated ZIP is written to RustFS, it is registered through <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/crates/app/src/modules/files/mod.rs" target="_blank" rel="noreferrer">Core Files</a>, which creates the File and a unique candidate location. The S3 conditional PUT uses <code>If-None-Match: *</code>, so an existing candidate can never be overwritten; after upload, the object&#39;s size, type and upload id are verified.</p><p>Finally the request is re-authorized and the lease validated, and one transaction adopts the ready file, links the export, writes the audit entry and marks the job succeeded. A timeout does not prove the remote write failed; unadopted candidates and pending files keep durable metadata that the later object-cleanup chapter reclaims.</p><p>Exports and snapshots are kept for 24 hours by default; expired queries show expired and no new links are issued. Downloads are restricted to the requester or an administrator, and both the current visitor and the original requester must still be able to read the source document. Existing short-lived links keep the TTL boundaries declared in the attachments tutorial; an export never becomes a permanently public URL. Physical deletion and expired-object cleanup are implemented in the deletion chapter.</p><h2 id="_6-configuration-and-verification" tabindex="-1">6. Configuration and verification <a class="header-anchor" href="#_6-configuration-and-verification" aria-label="Permalink to &quot;6. Configuration and verification&quot;">​</a></h2><p>The actual configuration comes from the <a href="./../reference/config">generated configuration reference</a>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>EXPORT_MAX_ATTACHMENTS</code></td><td>100</td><td>Caps the number of entries</td></tr><tr><td><code>EXPORT_MAX_INPUT_BYTES</code></td><td>256 MiB</td><td>Body plus attachments total</td></tr><tr><td><code>EXPORT_MAX_OUTPUT_BYTES</code></td><td>272 MiB</td><td>ZIP cap including directory and headers</td></tr><tr><td><code>EXPORT_TIMEOUT_SECS</code></td><td>120 s</td><td>Total budget for one execution</td></tr><tr><td><code>EXPORT_RETENTION_SECS</code></td><td>24 h</td><td>Export and snapshot lifetime</td></tr><tr><td><code>JOB_LEASE_SECS / JOB_HEARTBEAT_SECS</code></td><td>60 / 20 s</td><td>Job lease and renewals</td></tr><tr><td><code>JOB_SHUTDOWN_SECS</code></td><td>10 s</td><td>Worker shutdown wait</td></tr></tbody></table><p>Peak temporary disk usage is roughly input plus output caps, about 528 MiB per active export by default. Running out of disk fails that attempt; these caps are separate from the ordinary 20 MiB per-file attachment limit.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exports</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jobs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-storage.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generated_files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/exports.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>The HTTP/public-job tests verify publication across lease renewals, transaction release after a renewal timeout, visibility of new jobs beyond one page of history, idempotent snapshots, real ZIP/attachment bytes, session invalidation, audit rollback, permissions and expiry, missing objects and size limits. The storage adapter tests verify multi-part uploads and conditional writes; the View tests verify progress, request retry, failure, expiry and a denied download.</p><p>The request button, status badges (queued/running/retry_wait/succeeded/failed/expired), failure notes and expiry lines on the page all come from the shared bilingual catalog (<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/packages/views/src/knowledge/export-feedback.tsx" target="_blank" rel="noreferrer">export-feedback</a>) and render fully in either interface language; the idempotency, permission, attachment-packaging and link-expiry semantics are unchanged. The design-system showroom demos these states in isolation on demo data (UI09); the inbox side continues in <a href="./export-notifications">export result notifications</a>.</p><p>After this key journey passes, accept it in a real browser:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/e2e.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/exports.spec.ts</span></span></code></pre></div><p>The browser uploads an attachment and requests an export, a real Worker produces the ZIP, an independent JS ZIP library unpacks and verifies body and attachment bytes, and a final refresh confirms the result can be visited again. Day-to-day development keeps using the fast HTTP/View feedback.</p><p>When you build your own business, mirror &quot;enqueue in the business transaction → register a handler → commit the result within a valid lease&quot;; do not copy the queue implementation. The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">example ownership manifest</a> records the knowledge-base handlers, views, migrations, tests, configuration and tutorials; Core Jobs, Files, the Worker and the S3 adapters remain.</p><hr><p>Source version：<code>0b53e60ef0f0</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/docs/tutorials/10-document-exports.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,44)])])}const b=t(n,[["render",o]]);export{u as __pageData,b as default};
